package com.opendroid.ai.core.plugins

/**
 * Safe command profile for a separately configured Termux integration.
 *
 * This component intentionally executes only fixed, administrator-authored argument templates.
 * It is not a shell parser and must never accept a free-form command generated by an LLM.
 */
data class TermuxCommandTemplate(
    val id: String,
    val displayName: String,
    val executable: String,
    val fixedArguments: List<String>,
    val allowedArgumentNames: Set<String>,
    val mutating: Boolean,
    val maxOutputBytes: Int = 64 * 1024,
    val timeoutMillis: Long = 15_000
) {
    init {
        require(id.matches(Regex("[a-zA-Z0-9._-]{1,80}"))) { "Invalid template ID." }
        require(displayName.isNotBlank() && displayName.length <= 100)
        require(executable.startsWith("/") || executable.matches(Regex("[a-zA-Z0-9._+-]{1,80}"))) {
            "Executable must be an explicit path or safe executable name."
        }
        require(fixedArguments.size <= 64 && fixedArguments.all { it.length <= 512 })
        require(allowedArgumentNames.size <= 32 && allowedArgumentNames.all {
            it.matches(Regex("[a-zA-Z][a-zA-Z0-9_]{0,63}"))
        })
        require(maxOutputBytes in 1024..(1024 * 1024))
        require(timeoutMillis in 500..60_000)
    }

    /**
     * Substitution produces argument values, not a shell command. Callers must pass the returned
     * list to an API that accepts argv; never join it into a shell string.
     */
    fun buildArgv(arguments: Map<String, String>, userConfirmed: Boolean): List<String> {
        require(arguments.keys.all { it in allowedArgumentNames }) { "Unknown Termux argument." }
        require(!mutating || userConfirmed) { "This command changes state and needs user confirmation." }
        val rendered = fixedArguments.map { template ->
            Regex("\\{([a-zA-Z][a-zA-Z0-9_]*)}").replace(template) { match ->
                val key = match.groupValues[1]
                require(key in allowedArgumentNames) { "Template references an undeclared argument." }
                val value = arguments[key] ?: error("Missing argument: $key")
                require(value.length <= 1024 && value.none { it.code == 0 || it == '\n' || it == '\r' }) {
                    "Termux argument contains unsupported characters."
                }
                value
            }
        }
        require(rendered.none { it.contains('{') || it.contains('}') }) {
            "Unresolved placeholder in command template."
        }
        return listOf(executable) + rendered
    }
}

/** Built-in starter profiles are read-only and deliberately narrow. User must configure Termux. */
object TermuxReadOnlyTemplates {
    val templates = listOf(
        TermuxCommandTemplate(
            id = "termux.whoami",
            displayName = "Show current Termux user",
            executable = "whoami",
            fixedArguments = emptyList(),
            allowedArgumentNames = emptySet(),
            mutating = false
        ),
        TermuxCommandTemplate(
            id = "termux.pwd",
            displayName = "Show configured working directory",
            executable = "pwd",
            fixedArguments = emptyList(),
            allowedArgumentNames = emptySet(),
            mutating = false
        )
    )
}
